def unit_row(open_n=0):
    o = [bx(0, 0, -1.5, 4.0, 3.0, 0.1, 'greyD'), bx(0, 0, 0, 4.0, 0.05, 3.0, 'concrete'), bx(-1.95, 0, 0, 0.1, 3.0, 3.0, 'grey'), bx(1.95, 0, 0, 0.1, 3.0, 3.0, 'grey'), bx(0, 2.95, 0, 4.0, 0.1, 3.1, 'greyD')]
    o += [bx(-1.0, 0, 1.55, 1.9, 2.5, 0.06, 'orange'), bx(1.0, 0, 1.55, 1.9, 2.5, 0.06, 'orange')] if not open_n else [bx(-1.0, 2.2, 1.55, 1.9, 0.3, 0.06, 'orange'), bx(1.0, 0, 1.55, 1.9, 2.5, 0.06, 'orange')]
    o += [bx(sx, 0.4 + 0.45*i, 1.6, 1.7, 0.03, 0.02, 'blueD') for sx in (-1.0, 1.0) for i in range(5)]
    o += [bx(sx, 1.0, 1.6, 0.14, 0.14, 0.06, 'steel') for sx in (-1.0, 1.0)] + [bx(-1.0, 0.6, 1.64, 0.1, 0.1, 0.02, 'brass')]
    if open_n: o += [bx(-1.0, 0, -0.6, 1.2, 0.8, 0.8, 'cardboard'), bx(-1.0, 0.8, -0.6, 1.0, 0.6, 0.7, 'cardboard'), bx(-1.3, 0, 0.5, 0.6, 0.9, 0.6, 'wood'), bx(-0.6, 0, 0.6, 0.3, 0.3, 0.3, 'blueD')]
    return o
